class ProcessSaleService_AutoGenerated {
  /*SystemVariable Start*/
  CurrentCashDesk: CashDesk;
  CurrentStore: Store;
  /*SystemVariable End*/

  /*The current cash desk exists and the cash desk is opened.
   *There is no ongoing sale, or the current sale is complete.
   *Then a new sale is created.
   *The sale is linked to the current cash desk.
   *The sale is initialized is not complete and not ready to pay.
   *The sale is added to the system.
   *The new created sale will be used in other step*/
  makeNewSale(): boolean {
    /*Definition Start*/
    let cashDesk: CashDesk = l({
      logic: () => this.CurrentCashDesk,
      description: "self.CurrentCashDesk",
    }).build().pass;
    /*Definition End*/

    /*Precondition Start*/
    const { errorMessage: preconditionErrorMessage, pass: isPreconditionPass } =
      l({
        logic: () => StandardOPs.oclIsUndefined(cashDesk) === false,
        description: "cashDesk.oclIsUndefined()=false",
      })
        .and({
          logic: () => cashDesk.IsOpened === true,
          description: "cashDesk.IsOpened=true",
        })
        .and({
          logic: () =>
            l({
              logic: () => StandardOPs.oclIsUndefined(this.CurrentSale),
              description: "self.CurrentSale.oclIsUndefined()",
            }).or({
              logic: () => this.CurrentSale.IsComplete === true,
              description: "self.CurrentSale.IsComplete=true",
            }),
          description:
            "(self.CurrentSale.oclIsUndefined()orself.CurrentSale.IsComplete=true)",
        })
        .build();
    if (!isPreconditionPass) {
      throw new PreconditionError(preconditionErrorMessage);
    }
    /*Precondition End*/

    /*Postcondition Start*/
    let newSale: Sale;
    return l({
      execute: () => (newSale = new Sale()),
      description: "newSale.oclIsNew()",
    })
      .and({
        execute: () => (newSale.IsComplete = false),
        description: "newSale.IsComplete=false",
      })
      .and({
        execute: () => (newSale.IsReadytoPay = false),
        description: "newSale.IsReadytoPay=false",
      })
      .and({
        execute: () => (newSale.BelongedCashDesk = cashDesk),
        description: "newSale.BelongedCashDesk=cashDesk",
      })
      .and({
        execute: () => getRepository(Sale).push(newSale),
        description: "Sale.allInstance()->includes(newSale)",
      })
      .and({
        execute: () => (this.CurrentSale = newSale),
        description: "self.CurrentSale=newSale",
      })
      .and({
        execute: () => true,
        description: "result=true",
      })
      .build().value;
    /*Postcondition End*/
  }
}
export { ProcessSaleService_AutoGenerated };

